// user.cpp:

#include "Vector.h" // Vector의 인터페이스 가져오기
#include <cmath> // sqrt()를 포함하는 표준 라이브러리 수학 함수 인터페이스 가져오기

double sqrt_sum(Vector& v)
{
    double sum = 0;
    for (int i=0; i!=v.size(); ++i)
        sum+=std::sqrt(v[i]); // 제곱근의 합
    return sum;
}

// Vector.cpp 파일:
module; // module을 정의

// ... Vector 구현에 필요한 내용 작성 ...

export module Vector; // "Vector" 모듈 정의

export class Vector {
public:
    Vector(int s);
    double& operator[](int i);
    int size();
private:
    double* elem; // elem은 sz개의 double을 포함하는 배열을 가리킴
    int sz;
};

double& Vector::operator[](int i)
{
    if (i<0 || size()<=i)
        throw out_of_range{"Vector::operator[]"};
    return elem[i];
}

void f(Vector& v)
{
    // ...
    try { // 여기서 발생한 예외를 아래에 정의한 핸들러가 처리
        v[v.size()] = 7; // v의 끝을 넘어서 접근 시도
    }
    catch (out_of_range& err) { // out_of_range 예외
        // ... 스코프 밖 에러 처리...
        cerr << err.what() << '\n';
    }
    // ...
}

Vector::Vector(int s)
{
    if (s<0)
        throw length_error{"Vector 생성자: 크기가 음수임"};
    elem = new double[s];
    sz = s;
}

struct Entry {
